isVisible:
{{
  (() => {
    const statut = (Get_Location_Detail.data[0]?.Statut || '').trim().toLowerCase();

    // Le bouton sera visible (true) uniquement s'il est dans l'un de ces états
    return ['reservation', 'en cours', 'en_cours', 'terminé', 'termine'].includes(statut);
  })()
}}

onClick:
{{
  (async () => {
    const statut = Get_Location_Detail.data[0]?.Statut;

    // 1. Passage en départ
    if (statut === 'Reservation') {
      await Update_Statut.run({ newStatut: 'En Cours' });
      showAlert('Matériel marqué comme parti !', 'success');
      await Get_Location_Detail.run();
    } 
    // 2. Enregistrement du retour
    else if (statut === 'En Cours' || statut === 'En Cours') {
      await Update_Statut.run({ newStatut: 'Termine' });
      showAlert('Matériel retourné !', 'success');
      await Get_Location_Detail.run();
    } 
    // 3. Transfert en BL (Déclenche le trigger PostgreSQL)
    else if (statut === 'Terminé' || statut === 'Termine') {
      await Update_Statut.run({ newStatut: 'A_Transferer_BL' });
      showAlert('Transfert en BL effectué avec succès !', 'success');
      await Get_Location_Detail.run();
    }
  })()
}}

text:
{{
  (() => {
    const statut = (Get_Location_Detail.data[0]?.Statut || '').trim().toLowerCase();

    if (statut === 'reservation') return '🚀';
    if (statut === 'en cours' || statut === 'en_cours') return '📥';
    if (statut === 'terminé' || statut === 'termine') return '📄';

    return 'Aucune action';
  })()
}}

tooltip:
{{
  (() => {
    const statut = Get_Location_Detail.data[0]?.Statut;

    if (statut === 'Reservation') return '🚀 Valider le départ du matériel';
    if (statut === 'En Cours' || statut === 'En_Cours') return '📥 Enregistrer le retour du matériel';
    if (statut === 'Terminé' || statut === 'Termine') return '📄 Générer et transférer en Bon de Livraison';

    return 'Aucune action disponible';
  })()
}}
